SourceCode.Declaration:
/// <summary>
/// PB-355: Form notes matrix for customer statement descriptions.
/// </summary>
public class METCustStmtDescriptionSetup extends common
{
}

Method.Source:
public static METCustStmtDescriptionSetup find(
    METCustStmtTransType   _transType,
    METCustStmtIndustryKey _industryKey,
    boolean                _forUpdate = false)
{
    METCustStmtDescriptionSetup setup;

    if (_industryKey)
    {
        setup.selectForUpdate(_forUpdate);

        select firstonly setup
            where setup.TransType   == _transType
               && setup.IndustryKey == _industryKey;
    }

    return setup;
}

public static boolean exist(METCustStmtTransType _transType, METCustStmtIndustryKey _industryKey)
{
    return _industryKey
        && (select firstonly RecId from METCustStmtDescriptionSetup
                where METCustStmtDescriptionSetup.TransType   == _transType
                   && METCustStmtDescriptionSetup.IndustryKey == _industryKey).RecId != 0;
}

public boolean validateWrite()
{
    boolean ret = super();

    if (ret && !this.IndustryKey)
    {
        ret = checkFailed("@MET:METCustStmtIndustryKeyMandatory");
    }

    if (ret
        && (this.IndustryKey != this.orig().IndustryKey || this.TransType != this.orig().TransType)
        && METCustStmtDescriptionSetup::exist(this.TransType, this.IndustryKey))
    {
        ret = checkFailed(strFmt("@MET:METCustStmtIndustryKeyDuplicate", this.IndustryKey, this.TransType));
    }

    return ret;
}
